// CAT253: Complex Message Protocol (Fictional)
// Demonstrates advanced BMDL features:
// - Compulsory items in FSPEC (I010-I050 always set)
// - Message type discrimination via spare bits
// - Conditional item structures
// - Variable I100 format based on I080 selector
class Cat253Record {
public:
    static constexpr uint64_t TYPE_ID = 0x7f7b50444b289e0eULL;
    static constexpr std::string_view TYPE_NAME = "Cat253Record";

    const Cat253Record_items& items() const { return items_; }
    Cat253Record_items& mutable_items() { return items_; }
    void set_items(const Cat253Record_items& v) { items_ = v; }

    bool operator==(const Cat253Record&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        CONDUIT_TRY(items_.encode(w));
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253Record> decode(conduit::io::BitReader& r) {
        Cat253Record result;
        {
            auto val = Cat253Record_items::decode(r);
            if (!val) return std::unexpected(val.error());
            result.items_ = std::move(*val);
        }
        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat253Record{"
            << "items=" << items_.to_string()
            << "}";
        return oss.str();
    }

private:
    Cat253Record_items items_{};
public:
    conduit::Result<std::vector<uint8_t>> encode_bytes() const {
        conduit::io::BitWriter w;
        CONDUIT_TRY(encode(w));
        return w.finish();
    }

    static conduit::Result<Cat253Record> decode_bytes(std::span<const uint8_t> data, size_t max_bytes = 0) {
        if (max_bytes > 0 && data.size() > max_bytes) {
            return std::unexpected(conduit::Error(conduit::ErrorCode::MaxLengthExceeded,
                "message size " + std::to_string(data.size()) + " exceeds limit " + std::to_string(max_bytes)));
        }
        conduit::io::BitReader r(data);
        return decode(r);
    }
};

class items_i070 {
public:
    const uint8_t& v() const { return v_; }
    uint8_t& mutable_v() { return v_; }
    void set_v(const uint8_t& v) { v_ = v; }

    const uint8_t& g() const { return g_; }
    uint8_t& mutable_g() { return g_; }
    void set_g(const uint8_t& v) { g_ = v; }

    const uint8_t& l() const { return l_; }
    uint8_t& mutable_l() { return l_; }
    void set_l(const uint8_t& v) { l_ = v; }

    const mode3a_code& code() const { return code_; }
    mode3a_code& mutable_code() { return code_; }
    void set_code(const mode3a_code& v) { code_ = v; }

    bool operator==(const items_i070&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_bits(v_, 1);
        w.write_bits(g_, 1);
        w.write_bits(l_, 1);
        w.write_bits(0, 1);
        w.write_bits(code_, 12);
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<items_i070> decode(conduit::io::BitReader& r) {
        items_i070 result;
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("field 'v'"));
            result.v_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("field 'g'"));
            result.g_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("field 'l'"));
            result.l_ = static_cast<uint8_t>(*val);
        }
        CONDUIT_TRY(r.skip_bits(1));
        {
            auto val = r.read_bits(12);
            if (!val) return std::unexpected(val.error().with_context("field 'code'"));
            result.code_ = static_cast<mode3a_code>(*val);
        }
        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "items_i070{"
            << "v=" << +(v_)
            << ", g=" << +(g_)
            << ", l=" << +(l_)
            << ", code=0" << std::oct << static_cast<uint64_t>(code_) << std::dec
            << "}";
        return oss.str();
    }

private:
    uint8_t v_{};
    uint8_t g_{};
    uint8_t l_{};
    mode3a_code code_{};
};

class items_i090 {
public:
    const uint8_t& v() const { return v_; }
    uint8_t& mutable_v() { return v_; }
    void set_v(const uint8_t& v) { v_ = v; }

    const uint8_t& g() const { return g_; }
    uint8_t& mutable_g() { return g_; }
    void set_g(const uint8_t& v) { g_ = v; }

    const double& fl() const { return fl_; }
    double& mutable_fl() { return fl_; }
    void set_fl(const double& v) { fl_ = v; }

    bool operator==(const items_i090&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_bits(v_, 1);
        w.write_bits(g_, 1);
        w.write_signed_bits(static_cast<int16_t>(fl_ / 0.25), 14);
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<items_i090> decode(conduit::io::BitReader& r) {
        items_i090 result;
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("field 'v'"));
            result.v_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("field 'g'"));
            result.g_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_signed_bits(14);
            if (!val) return std::unexpected(val.error().with_context("field 'fl'"));
            result.fl_ = static_cast<double>(*val) * 0.25 + 0;
        }
        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "items_i090{"
            << "v=" << +(v_)
            << ", g=" << +(g_)
            << ", fl=" << +(fl_)
            << "}";
        return oss.str();
    }

private:
    uint8_t v_{};
    uint8_t g_{};
    double fl_{};
};

